// Chat AI - frontend, 4 Nov 2026: AICHAT-1334 batch (push 12:25 UTC, aichat-frontend PR #920). Tag AICHAT-1334 (merge_tags) + description where empty. Never replace existing text.
const CTX = ' | Sign-in modal on chatbotonline.ai, "Check your email" step (after the user enters an email and a sign-in link is sent). The sign-in link can only be resent after a wait (rate limit against spam); ';
const DESCS = {
  '972779727': CTX + 'this line replaces the "Resend link" option while the wait is under 1 minute and counts down live. {seconds} = seconds left. "The link" = the sign-in link sent by email. Keep the ICU plural syntax and the # exactly as is; translate only the words and add the plural forms your language needs. Ticket AICHAT-1334.',
  '972779728': CTX + 'this line replaces the "Resend link" option while the wait is 1 minute or more. {minutes} = minutes left (rounded up). "The link" = the sign-in link sent by email. Keep the ICU plural syntax and the # exactly as is; translate only the words and add the plural forms your language needs. Ticket AICHAT-1334.',
  '972779729': ' | Error message in the sign-in modal on chatbotonline.ai, shown when a sign-in link request is refused because too many requests came from the same internet connection (IP address) in a short time. "Your network" = the user\'s internet connection, not a social network. {minutes} = wait time in minutes (rounded up). Keep the ICU plural syntax and the # exactly as is; translate only the words and add the plural forms your language needs. Ticket AICHAT-1334.'
};
const ONLY = ['972779728','972779729'];
return [{ json: { project_id: '691331356a3b9a68428ab3.43540470', tag: 'AICHAT-1334', descs: DESCS, key_ids: ONLY.length ? ONLY : Object.keys(DESCS) } }];

// Guards: skip archived; tag with merge_tags; description = existing + appended context, skipped if it already mentions the ticket. Never replaces text.
const p = $('Params').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const out = []; const skipped = []; const before = []; const expected = {};
for (const id of p.key_ids) {
  const k = byId[id]; if (!k || k.is_archived) { skipped.push({ id: id, why: 'missing/archived' }); continue; }
  before.push({ id: k.key_id, description: k.description || '', tags: k.tags });
  const cur = String(k.description || '').trim();
  const item = { key_id: Number(id), tags: [p.tag], merge_tags: true };
  if (cur.indexOf(p.tag) === -1) { item.description = cur ? cur + p.descs[id] : p.descs[id].replace(/^ \| /, ''); }
  else { skipped.push({ id: id, why: 'description already mentions ' + p.tag }); }
  expected[id] = item.description || cur;
  out.push(item);
}
if (out.length === 0) { throw new Error('Nothing to write: ' + JSON.stringify(skipped)); }
return [{ json: { body: { keys: out }, skipped: skipped, before: before, expected: expected, plan: out.map(function (x) { return x.key_id; }) } }];

const p = $('Params').first().json; const B = $('Build').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const oldTags = {}; for (const b of B.before) { oldTags[b.id] = b.tags || []; }
const res = B.plan.map(function (id) { const k = byId[id] || {}; const tags = k.tags || []; const keptOld = (oldTags[id] || []).every(function (t) { return tags.indexOf(t) !== -1; }); return { id: id, ok: k.description === B.expected[String(id)] && tags.indexOf(p.tag) !== -1 && keptOld, description: k.description, tags: tags }; });
const bad = res.filter(function (x) { return !x.ok; });
return [{ json: { ok: bad.length === 0, results: res, skipped: B.skipped, bad: bad } }];

// Lokalise returned 500 on a 40-key PUT: send 10 keys per call.
const out = [];
for (const it of $input.all()) { const ks = it.json.body.keys; for (let i = 0; i < ks.length; i += 10) { out.push({ json: { body: { keys: ks.slice(i, i + 10) } } }); } }
return out;
